-- Counts: 1274 creatures, 3822 creature_equip_template pool rows, 1274 outfit rows, 5096 outfit variant rows, 9917 spawn rows updated.
-- Rule: creature_level = creature_template.maxlevel; ItemLevel in [creature_level, creature_level + 8], RequiredLevel <= creature_level + 3, Quality <= 2; pick index (entry + variant) % len(candidates) for weapon pool variants, (entry + slot index) % len(candidates) for the six fixed outfit slots and (entry + slot index + variant) % len(candidates) for the five varying ones.
-- Rule: candidate positions are two-hander {17, 21}, main hand {13, 21, 22} and ranged {15, 25, 26} from item class 2; the off-hand position mixes classes — class 2 with {13, 22} plus class 4 with {14 shield, 23 holdable} — so shields and off-hand frills can fill ItemID2.
-- Rule: every candidate list is ordered bind-on-equip first — (bonding != 2, ItemLevel, entry) — so the drop half (CreatureGear.Drop.RequireBindOnEquip = 1) always has a droppable item.
-- Per-spawn armour variants. The module picks one variant per spawn point (spawn id % variant
-- count) and uses the same pick when the creature drops its gear, so a corpse yields the armour
-- its spawn point showed. The six slots not listed here stay on `mod_creature_gear_outfit`,
-- which is also the fallback for a creature without variant rows.

CREATE TABLE IF NOT EXISTS `mod_creature_gear_outfit_variant` (
  `CreatureID` int unsigned NOT NULL,
  `Variant` tinyint unsigned NOT NULL,
  `Head` int unsigned NOT NULL DEFAULT '0',
  `Chest` int unsigned NOT NULL DEFAULT '0',
  `Legs` int unsigned NOT NULL DEFAULT '0',
  `Feet` int unsigned NOT NULL DEFAULT '0',
  `Hands` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`CreatureID`, `Variant`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

